import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.B_zcDAFh.js";const l=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),d={name:"guide/architecture.md"};function c(s,e,n,i,p,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p><code>BoingManager</code> is a static registry and scheduler. Components self-register on enable/disable, and on the first registration the manager spawns a hidden <code>DontDestroyOnLoad</code> GameObject carrying two pump components: <code>BoingManagerPostUpdatePump</code> and <code>BoingManagerPreUpdatePump</code>.</p><p>The post-update pump drives <code>BoingManager.Execute(...)</code> and <code>Pull*Results(...)</code> in <code>FixedUpdate</code>, <code>Update</code> (EarlyUpdate), and <code>LateUpdate</code>. The pre-update pump runs at the start of the next frame and calls <code>Restore*</code> plus <code>DispatchReactorFieldCompute</code> — GPU dispatch is deferred one frame so compute work can complete.</p><p>The per-frame phase order inside <code>BoingManager.Execute</code> is bones first (so they see unmodified transforms), then behaviors, then reactors. Bone results are pulled last so bone transforms don&#39;t inherit their parent&#39;s just-applied delta. This ordering matters — preserve it when touching the pumps.</p>',4)])])}const m=t(d,[["render",c]]);export{l as __pageData,m as default};
